fn is_2_pow(n: i32) -> bool {
    n > 0 && (n & (n - 1)) == 0
}

fn search_range_helper(a: &[i32], x: i32, lo: usize, hi: usize) -> usize {
    // Binary search for the lower‐bound of x in a[lo..hi).
    // Returns the smallest k in [lo..hi] such that a[k] >= x,
    // or hi if all elements in [lo..hi) are < x.
    let mut low = lo;
    let mut high = hi;
    while low < high {
        let mid = low + (high - low) / 2;
        if a[mid] < x {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    low
}

fn search_1000(a: &[i32], x: i32) -> usize {
    // We assume a.len() >= 1000 and a[0..1000] is sorted.
    // We want the lower‐bound insertion index k in [0..1000].
    search_range_helper(a, x, 0, 1000)
}

